def summarize_ranges(nums: list[int]) -> str:
    # Handle empty list
    if not nums:
        return ""

    # Sort the numbers and remove duplicates
    sorted_nums = sorted(set(nums))

    # If list is empty after processing (e.g., all duplicates or initially empty)
    if not sorted_nums:
        return ""

    parts = []
    current_group = [sorted_nums[0]]

    for num in sorted_nums[1:]:
        # Check if the current number is consecutive to the last number in the group
        if num == current_group[-1] + 1:
            current_group.append(num)
        else:
            # The consecutive run has ended
            start, end = current_group[0], current_group[-1]
            run_length = len(current_group)

            if run_length >= 3:
                # Run of 3 or more consecutive integers
                parts.append(f"{start}..{end}")
            else:
                # Run of 1 or 2 integers, list individually
                for n in current_group:
                    parts.append(str(n))

            # Start a new group with the current number
            current_group = [num]

    # Process the final group
    start, end = current_group[0], current_group[-1]
    run_length = len(current_group)
    if run_length >= 3:
        parts.append(f"{start}..{end}")
    else:
        for n in current_group:
            parts.append(str(n))

    return ",".join(parts)
